import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Find preferences and keyboard controls","description":"","frontmatter":{"title":"Find preferences and keyboard controls","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","order":10},"headers":[],"relativePath":"en/user/preferences/index.md","filePath":"en/user/preferences/index.md","lastUpdated":1795731074000}`),s={name:`en/user/preferences/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">Find preferences and keyboard controls <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to “Find preferences and keyboard controls”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Set the application language, find the correct configuration area and use supported keyboard controls comfortably. You need the desktop window open; network access is only required for the service being configured.</p><h2 id="find-the-relevant-setting" tabindex="-1">Find the relevant setting <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to “Find the relevant setting”">​</a></h2><ol><li>Open <strong>Settings → General</strong> to choose the interface language. Current choices are English (<code>en</code>), Spanish (<code>es</code>), Portuguese (<code>pt</code>), French (<code>fr</code>), Simplified Chinese (<code>zh</code>) and Japanese (<code>ja</code>). Language selection does not change TikTok event identifiers or plugin API names.</li><li>Review the updater controls in General: channel, automatic checks, notifications and a manual check when supported. Automatic checks are optional. Signed update availability depends on the build&#39;s published signing configuration.</li><li>Use <strong>Account</strong> for Cloud identity and its diagnostics. Use <strong>Collaboration</strong> for owner access configuration, and <strong>Teams</strong> when the host exposes that capability.</li><li>Open <strong>Plugins</strong> for plugin-wide preferences and each plugin&#39;s Settings/Connection panes. A plugin&#39;s service credentials do not belong in General settings.</li><li>Open <strong>Automations → Variables</strong> for shared runtime values, <strong>Points</strong> for earning rules and <strong>Overlays</strong> for widget design. These configuration surfaces are intentionally located beside the features they affect.</li></ol><p>Automatic installation is experimental and disabled by the current release workflow&#39;s build gates. A visible automatic-check preference does not promise automatic installation. Use the documented <a href="./../updates.html">update process</a> and make a <a href="./backups.html">backup</a> before a version change.</p><h2 id="use-supported-keyboard-controls" tabindex="-1">Use supported keyboard controls <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to “Use supported keyboard controls”">​</a></h2><p>Use Tab and Shift+Tab to move focus through ordinary controls and Enter/Space to activate focused buttons. In the overlay design inspector, Ctrl/Meta+Z undoes and Ctrl/Meta+Shift+Z or Ctrl/Meta+Y redoes. Text inputs retain their own undo behavior. These are editor shortcuts, not global automation hotkeys.</p><p>Escape closes the narrow navigation drawer when another control has not consumed it. Dialogs and editors may handle Escape themselves, including an unsaved-change prompt. Global hotkey automation requires a compatible installed plugin and its reported backend capabilities.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Expected result, status and recovery”">​</a></h2><p>These settings and local keyboard interactions are available; complete accessibility/platform acceptance is not claimed. Prefer labeled buttons, readable window sizes and paused feed scrolling when movement is distracting. If a setting appears missing, check its owning page and host capability before resetting data. See <a href="./troubleshooting.html">troubleshooting</a> for unavailable controls and <a href="./faq.html">FAQ</a> for common distinctions.</p>`,11),t(d,{scenario:`settings`,locale:`en`,title:`Demo: settings`})])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};